-- =============================================================================
-- 478 — LE CAHIER D'EXERCICES DE 5E (partie 7)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/5e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 478 --niveau 5e --fichiers physique-chimie.n2,physique-chimie.n3,sport.jumelles --suffixe 7 > supabase/contenu/478_exercices_5e_7.sql
--
-- 84 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   physique-chimie.n2      33 exercices · 11 chapitres
--   physique-chimie.n3      27 exercices · 9 chapitres
--   sport.jumelles          24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('325b9123-94f9-5ab6-a91e-c0f05f425523'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le Système solaire du club d’astronomie","competence":"observer-schema","situation":"Pour le club d’astronomie, Inès dessine le Système solaire sur le tableau. Elle a rangé les planètes dans l’ordre en partant du Soleil.","documents":[{"id":"systeme","type":"schema","titre":"Le dessin d’Inès","largeur":340,"hauteur":200,"elements":[{"forme":"cercle","cx":30,"cy":100,"r":26,"teinte":"jaune","motif":"plein","id":"z1","zone":true},{"forme":"texte","x":30,"y":145,"texte":"Soleil","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":78,"cy":100,"r":4,"teinte":"gris","motif":"plein","id":"z2","zone":true},{"forme":"texte","x":78,"y":68,"texte":"Mercure","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":104,"cy":100,"r":6,"teinte":"ambre","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":104,"y":146,"texte":"Vénus","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":130,"cy":100,"r":6,"teinte":"bleu","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":130,"y":68,"texte":"Terre","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":156,"cy":100,"r":5,"teinte":"corail","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":156,"y":146,"texte":"Mars","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":192,"cy":100,"r":14,"teinte":"sable","motif":"plein","id":"z6","zone":true},{"forme":"texte","x":192,"y":68,"texte":"Jupiter","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":232,"cy":100,"r":12,"teinte":"jaune","motif":"plein","id":"z7","zone":true},{"forme":"texte","x":232,"y":146,"texte":"Saturne","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":268,"cy":100,"r":9,"teinte":"turquoise","motif":"plein","id":"z8","zone":true},{"forme":"texte","x":268,"y":68,"texte":"Uranus","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":303,"cy":100,"r":9,"teinte":"violet","motif":"plein","id":"z9","zone":true},{"forme":"texte","x":303,"y":146,"texte":"Neptune","ancre":"milieu","taille":"petit"},{"forme":"texte","x":170,"y":185,"texte":"Tailles et distances non respectées","ancre":"milieu","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’étoile du Système solaire, celle qui produit sa propre lumière.","aide":"Parmi les astres dessinés, une seule étoile est au centre du système.","type":"zone","document":"systeme","multiple":false},{"enonce":"Touche les quatre planètes gazeuses.","aide":"Les planètes gazeuses sont les quatre plus éloignées du Soleil.","type":"zone","document":"systeme","multiple":true},{"enonce":"Combien de planètes sont plus proches du Soleil que la Terre ?","aide":"Compte les astres dessinés entre le Soleil et la Terre.","type":"nombre","unite":"planètes"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **Soleil** est une étoile : il produit sa propre lumière. Les planètes ne font que la diffuser."},{"cle":{"type":"zone","ids":["z6","z7","z8","z9"]},"explication":"Les planètes gazeuses sont **Jupiter, Saturne, Uranus et Neptune**. Les quatre plus proches (Mercure, Vénus, la Terre, Mars) sont telluriques, donc rocheuses."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 planètes","explication":"Entre le Soleil et la Terre, il y a **Mercure et Vénus** : 2 planètes."}]$ex$::jsonb),
  ('325b9123-94f9-5ab6-a91e-c0f05f425523'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Combien de temps la lumière met-elle pour arriver ?","competence":"lire-tableau","situation":"Pour un exposé, Malo a relevé le temps que met la lumière à nous parvenir depuis trois astres. Il veut en déduire les distances. La lumière va à 300 000 km/s dans le vide.","documents":[{"id":"duree","type":"tableau","titre":"Durée du trajet de la lumière","colonnes":["Astre","Durée du trajet"],"lignes":[["Lune","1,3 s"],["Soleil","500 s"],["Neptune","4,0 h"]],"enteteLignes":true,"source":"Valeurs simplifiées pour l’exercice"}],"questions":[{"enonce":"Quelle est la distance Terre-Lune, en km ? (d = v × t)","aide":"Multiplie la vitesse de la lumière en km/s par la durée en secondes.","type":"nombre","unite":"km"},{"enonce":"Touche l’astre dont la lumière met le plus de temps à nous parvenir.","aide":"Compare les durées : attention, une est en heures et les autres en secondes.","type":"zone","document":"duree","multiple":false},{"enonce":"Quelle distance la lumière parcourt-elle en 4,0 h pour atteindre Neptune ? Réponds en milliards de km.","aide":"Convertis d’abord 4,0 h en secondes (1 h = 3 600 s), puis applique d = v × t.","type":"nombre","unite":"milliards de km"},{"enonce":"Quand Malo regarde la Lune, comment la voit-il ?","aide":"La lumière met du temps pour venir jusqu’à nous : regarder loin, c’est regarder tôt.","type":"choix","options":[{"id":"a","texte":"Telle qu’elle sera dans 1,3 s"},{"id":"b","texte":"Telle qu’elle était il y a 500 s"},{"id":"c","texte":"Telle qu’elle est à cet instant précis"},{"id":"d","texte":"Telle qu’elle était il y a 1,3 s"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":390000,"tolerance":0},"affichage":"390 000 km","explication":"On utilise **d = v × t** : d = 300 000 km/s × 1,3 s = **390 000 km**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"4,0 h, c’est beaucoup plus que 500 s : c’est **Neptune**, le plus lointain."},{"cle":{"type":"nombre","valeur":4.32,"tolerance":0},"affichage":"4,32 milliards de km","explication":"4,0 h = 14 400 s. **d = v × t** = 300 000 × 14 400 = 4 320 000 000 km, soit **4,32 milliards de km**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La lumière de la Lune met 1,3 s : on la voit **telle qu’elle était il y a 1,3 s**."}]$ex$::jsonb),
  ('325b9123-94f9-5ab6-a91e-c0f05f425523'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un message radio vers le robot de Mars","competence":"lire-graphique","situation":"Une sonde est posée sur Mars. Léa travaille au centre de contrôle : le message qu’elle envoie voyage à la vitesse de la lumière. Elle veut savoir combien de temps il met pour aller sur Mars, puis pour recevoir la réponse.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Distance parcourue par la lumière","categories":["0 s","100 s","200 s","300 s","400 s","500 s"],"series":[{"nom":"Distance","valeurs":[0,30,60,90,120,150],"teinte":"violet"}],"axeY":{"titre":"Distance parcourue","unite":"en millions de km","min":0,"max":150,"pas":30},"axeX":{"titre":"Durée du trajet"},"source":"Calculs avec 300 000 km/s"},{"id":"dist","type":"tableau","titre":"Distance de la Terre","colonnes":["Astre","Distance (millions de km)"],"lignes":[["Mars","225"],["Jupiter","780"]],"enteteLignes":true,"source":"Distances arrondies, à un moment donné"}],"questions":[{"enonce":"Lis la courbe : quelle distance la lumière parcourt-elle en 300 s ?","aide":"Cherche le point de la courbe sous 300 s et lis sa hauteur sur l’axe vertical.","type":"nombre","unite":"millions de km"},{"enonce":"Mars est à 225 millions de km. Combien de secondes le message met-il pour y arriver ?","aide":"Pense à d = v × t, donc t = d ÷ v. Écris 225 millions de km avec tous ses zéros.","type":"nombre","unite":"s"},{"enonce":"Léa reçoit la réponse après un aller-retour. Combien de minutes cela fait-il ?","aide":"Un aller-retour, c’est deux trajets de 750 s.","type":"nombre","unite":"min"},{"enonce":"Même question pour Jupiter (780 millions de km) : combien de secondes met la lumière pour un aller simple ?","aide":"Applique la même relation, avec 780 000 000 km.","type":"nombre","unite":"s"},{"enonce":"Proxima du Centaure est à 4,2 années-lumière. Qu’observe-t-on quand on la regarde ?","aide":"Une année-lumière, c’est la distance parcourue par la lumière en un an.","type":"choix","options":[{"id":"a","texte":"Telle qu’elle était il y a 4,2 minutes"},{"id":"b","texte":"Telle qu’elle était il y a 4,2 ans"},{"id":"c","texte":"Telle qu’elle sera dans 4,2 ans"},{"id":"d","texte":"Telle qu’elle est aujourd’hui"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":90,"tolerance":0},"affichage":"90 millions de km","explication":"Au point 300 s, la courbe est à **90 millions de km** (300 000 km/s × 300 s = 90 000 000 km)."},{"cle":{"type":"nombre","valeur":750,"tolerance":0},"affichage":"750 s","explication":"t = d ÷ v = 225 000 000 km ÷ 300 000 km/s = **750 s**."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 min","explication":"Aller-retour : 2 × 750 s = 1 500 s, soit 1 500 ÷ 60 = **25 min**."},{"cle":{"type":"nombre","valeur":2600,"tolerance":0},"affichage":"2600 s","explication":"t = d ÷ v = 780 000 000 ÷ 300 000 = **2 600 s**, soit un peu plus de 43 minutes."},{"cle":{"type":"choix","ids":["b"]},"explication":"La lumière met 4,2 ans : on voit Proxima **telle qu’elle était il y a 4,2 ans**."}]$ex$::jsonb),
  ('5e15eaa3-663a-5071-9b8e-0353e35d0887'::uuid, 1, 1, 5, 20, 3,
