tres.","type":"ordre","items":[{"id":"a","texte":"Le Soleil et les planètes se forment"},{"id":"b","texte":"Une étoile fabrique du carbone en son cœur"},{"id":"c","texte":"Les atomes se retrouvent dans un nuage de gaz"},{"id":"d","texte":"L’étoile explose et disperse ses atomes"}]},{"enonce":"Que veut dire « nous sommes faits de poussières d’étoiles » ?","aide":"Reviens à l’origine du carbone et de l’oxygène.","type":"choix","options":[{"id":"a","texte":"Beaucoup de nos atomes ont été fabriqués dans des étoiles"},{"id":"b","texte":"Notre corps contient de petites étoiles"},{"id":"c","texte":"Notre corps brille comme une étoile"},{"id":"d","texte":"Nous sommes faits d’atomes qui n’existent que sur Terre"}],"multiple":false}]}$ex$::jsonb,
