   $ex${"titre":"Les formules de la cuisine","competence":"analyser-document","situation":"Dans la cuisine d’Amine, plusieurs substances portent une formule chimique : l’eau du robinet, l’eau gazeuse, le gaz de la gazinière, un colorant bleu. Il veut comprendre ce que disent les formules.","documents":[{"id":"formules","type":"tableau","titre":"Formules relevées","colonnes":["Nom","Formule"],"lignes":[["Eau","H₂O"],["Dioxygène","O₂"],["Dioxyde de carbone","CO₂"],["Méthane","CH₄"],["Monoxyde de carbone","CO"],["Cobalt (colorant bleu)","Co"]],"enteteLignes":true,"source":"Formules du cours"}],"questions":[{"enonce":"Classe ces écritures : un seul atome ou une molécule ?","aide":"Une molécule est un assemblage d’atomes ; regarde les majuscules : « Co » n’en a qu’une.","type":"categories","categories":[{"id":"c0","texte":"Un seul atome"},{"id":"c1","texte":"Une molécule"}],"items":[{"id":"i0","texte":"CO (monoxyde de carbone)"},{"id":"i1","texte":"CH₄ (méthane)"},{"id":"i2","texte":"Co (cobalt)"},{"id":"i3","texte":"O₂ (dioxygène)"}]},{"enonce":"Touche la formule de la molécule qui contient exactement 5 atomes.","aide":"L’indice compte les atomes qui le précèdent ; additionne tous les atomes.","type":"zone","document":"formules","multiple":false},{"enonce":"Combien d’atomes contiennent en tout 2 molécules de dioxyde de carbone (CO₂) ?","aide":"Compte d’abord les atomes d’une seule molécule CO₂.","type":"nombre","unite":"atomes"},{"enonce":"Un atome d’hydrogène a 1 proton et un atome d’oxygène en a 8. Combien de protons y a-t-il dans une molécule d’eau H₂O ?","aide":"H₂O : deux atomes d’hydrogène et un atome d’oxygène.","type":"nombre","unite":"protons"},{"enonce":"Les écritures « Co » et « CO » désignent-elles la même substance ?","aide":"Compte les majuscules dans chaque écriture.","type":"choix","options":[{"id":"a","texte":"Non, la casse change la substance"},{"id":"b","texte":"Oui, la casse n’a pas d’importance"},{"id":"c","texte":"Oui, ce sont deux écritures du cobalt"},{"id":"d","texte":"Non, mais seulement à l’oral"}],"multiple":false}]}$ex$::jsonb,
