ns.","aide":"Une interaction de contact exige que les objets se touchent.","type":"categories","categories":[{"id":"c0","texte":"De contact"},{"id":"c1","texte":"À distance"}],"items":[{"id":"i0","texte":"Les frottements de l’air sur un vélo"},{"id":"i1","texte":"La main qui pousse un chariot"},{"id":"i2","texte":"La Terre qui attire la Lune"},{"id":"i3","texte":"Le sol qui soutient un livre"},{"id":"i4","texte":"Un aimant qui attire un clou"}]},{"enonce":"Touche la flèche qui représente la force exercée par le mur sur le skateur.","aide":"C’est cette force qui éloigne le skateur du mur : dans quel sens est-il poussé ?","type":"zone","document":"mur","multiple":false},{"enonce":"Le skateur pousse le mur avec une force de 80 N. Quelle est la valeur de la force exercée par le mur sur le skateur ?","aide":"C’est le principe des actions réciproques.","type":"nombre","unite":"N"}]}$ex$::jsonb,
