eur":210,"elements":[{"forme":"rect","x":20,"y":130,"l":300,"h":12,"teinte":"sable","motif":"plein"},{"forme":"rect","x":130,"y":100,"l":80,"h":30,"teinte":"gris","motif":"plein","texte":"Palet"},{"forme":"ligne","de":[150,115],"a":[150,185],"fleche":"fin","teinte":"violet","id":"z7","zone":true},{"forme":"texte","x":135,"y":180,"texte":"A","ancre":"milieu","taille":"normal","gras":true},{"forme":"ligne","de":[195,100],"a":[195,30],"fleche":"fin","teinte":"violet","id":"z8","zone":true},{"forme":"texte","x":212,"y":40,"texte":"B","ancre":"milieu","taille":"normal","gras":true},{"forme":"ligne","de":[130,115],"a":[70,115],"fleche":"fin","teinte":"violet","id":"z9","zone":true},{"forme":"texte","x":95,"y":104,"texte":"C","ancre":"milieu","taille":"normal","gras":true},{"forme":"ligne","de":[250,80],"a":[310,80],"fleche":"fin","teinte":"gris"},{"forme":"texte","x":280,"y":70,"texte":"Mouvement","ancre":"milieu","taille":"petit"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Entre M0 et M3, deux positions voisines sont séparées de 40 unités, soit 1 m. Quelle est la vitesse du palet, en m/s ?","aide":"v = d ÷ t avec d = 1 m et t = 0,2 s.","type":"nombre","unite":"m/s"},{"enonce":"Touche la première position où l’on voit que le palet a ralenti (écart plus petit que d’habitude).","aide":"Cherche le premier écart plus petit que 40 unités.","type":"zone","document":"palet","multiple":false},{"enonce":"Entre M0 et M3, que peut-on dire des forces qui s’exercent sur le palet ?","aide":"Le palet garde une vitesse constante sur une ligne droite.","type":"choix","options":[{"id":"a","texte":"Elles ne se compensent pas"},{"id":"b","texte":"Il n’y a aucune force"},{"id":"c","texte":"Le palet est poussé en continu"},{"id":"d","texte":"Elles se compensent"}],"multiple":false},{"enonce":"Touche la force qui explique que le palet ralentisse sur le sable.","aide":"Cette force s’oppose au mouvement : de quel côté pointe-t-elle ?","type":"zone","document":"forces","mul