}],"multiple":false},{"enonce":"Le conducteur regarde son téléphone. Quelle distance s’allonge ?","aide":"Qu’est-ce qui change : le temps pour réagir ou la façon de freiner ?","type":"choix","options":[{"id":"a","texte":"Aucune des deux"},{"id":"b","texte":"Les deux de la même façon"},{"id":"c","texte":"La distance de freinage"},{"id":"d","texte":"La distance de réaction"}],"multiple":false}]}$ex$::jsonb,
