aide":"Cherche l’endroit couvert par les trois cercles à la fois.","type":"zone","document":"projecteurs","multiple":false},{"enonce":"Complète la conclusion de Sacha.","aide":"C’est le principe des écrans de télévision et de téléphone.","type":"trous","segments":["Le mélange des trois lumières rouge, verte et bleue donne du ",0," : c’est la synthèse ",1,"."],"banque":["additive","soustractive","noir","blanc"]}]}$ex$::jsonb,
