"Infrason"},{"id":"c1","texte":"Son audible"},{"id":"c2","texte":"Ultrason"}],"items":[{"id":"i0","texte":"Violoncelle"},{"id":"i1","texte":"Flûte"},{"id":"i2","texte":"Grondement d’éléphant"},{"id":"i3","texte":"Cri de chauve-souris"}]}]}$ex$::jsonb,
