ment.","aide":"Pense aux gestes de gagner sans mépriser et perdre sans accuser.","type":"categories","categories":[{"id":"c0","texte":"Fair-play"},{"id":"c1","texte":"Pas de fair-play"}],"items":[{"id":"i0","texte":"Serrer la main de tous"},{"id":"i1","texte":"Accuser l’arbitre"},{"id":"i2","texte":"Se moquer des perdants"},{"id":"i3","texte":"Aider un adversaire à terre"}]},{"enonce":"Relie chaque valeur olympique à ce qu’elle demande.","aide":"Les trois valeurs sont excellence, amitié, respect.","type":"association","gauche":[{"id":"g0","texte":"Excellence"},{"id":"g1","texte":"Amitié"},{"id":"g2","texte":"Respect"}],"droite":[{"id":"d0","texte":"De la règle, de l’adversaire, de soi"},{"id":"d1","texte":"Donner son meilleur"},{"id":"d2","texte":"Placer le lien avant le résultat"}]}]}$ex$::jsonb,
