on apprendre au PSC1, dès le collège ?","aide":"PSC1 signifie prévention et secours civiques de niveau 1.","type":"choix","options":[{"id":"a","texte":"À remplacer les secours dans toutes les situations"},{"id":"b","texte":"Position latérale, massage cardiaque, défibrillateur"},{"id":"c","texte":"À arbitrer un match sans se tromper jamais"},{"id":"d","texte":"À soigner seul une fracture ouverte"}],"multiple":false}]}$ex$::jsonb,
