  ('dad0f425-8717-590c-b8cb-f13de4ff0ba0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre élèves, quatre problèmes","competence":"analyser-document","situation":"En fin de trimestre, la professeure demande à quatre élèves de raconter le moment le plus difficile de leur cycle… sans dire le nom de l’activité. À toi de retrouver le problème que chacun a dû résoudre.","documents":[{"id":"recits","type":"dialogue","modele":"bulles","titre":"Ce qu’ils racontent","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"},{"nom":"Maëlle","emoji":"👩","cote":"gauche"},{"nom":"Tom","emoji":"🧒","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Arrivée tout en haut du mur, j’ai regardé en bas… Pour redescendre, il a fallu faire confiance à la corde et à mon assureur."},{"qui":"Yanis","texte":"Le défenseur a foncé sur moi. J’avais une seconde pour choisir : faire la passe à Inès ou tirer."},{"qui":"Maëlle","texte":"Le plus dur, c’était les regards de toute la classe sur notre enchaînement. On a répété nos figures jusqu’à ne plus avoir le trac."},{"qui":"Tom","texte":"En septembre, je courais le 1 000 m en 6 min 10 s. En décembre, en 5 min 50 s !"}]}],"questions":[{"enonce":"Relie chaque élève au champ d’apprentissage qu’il décrit.","aide":"Cherche l’indice de chaque bulle : un milieu qui fait peur, un adversaire, un public qui regarde, un chronomètre.","type":"association","gauche":[{"id":"g0","texte":"Lina"},{"id":"g1","texte":"Yanis"},{"id":"g2","texte":"Maëlle"},{"id":"g3","texte":"Tom"}],"droite":[{"id":"d0","texte":"Conduire un affrontement (champ 4)"},{"id":"d1","texte":"Adapter son déplacement (champ 2)"},{"id":"d2","texte":"S’exprimer devant les autres (champ 3)"},{"id":"d3","texte":"Produire une performance mesurée (champ 1)"}]},{"enonce":"Dans le champ 4, il faut **décider vite**. Touche le mot de Yanis qui montre qu’il avait très peu de temps pour choisir.","aide":"Relis la bulle de Yanis : combien de temps avait-il avant que le défenseur n’arrive ?","type":"zone","document":"recits","multiple":false},{"enonce":"De combien de **secondes** Tom a-t-il amélioré son temps au 1 000 m entre septembre et décembre ?","aide":"Attention : 1 minute = 60 secondes. De 6 min 10 s à 6 min, puis de 6 min à 5 min 50 s, combien de secondes en tout ?","type":"nombre","unite":"s"},{"enonce":"En calculant ces 20 secondes, quel critère d’évaluation de l’EPS viens-tu de mesurer pour Tom ?","aide":"Tu n’as pas regardé un seul temps, mais l’écart entre son temps d’arrivée et son point de départ.","type":"choix","options":[{"id":"a","texte":"La performance"},{"id":"b","texte":"La méthode"},{"id":"c","texte":"La progression"},{"id":"d","texte":"Le rôle tenu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"Lina grimpe en hauteur : **champ 2** (sa sécurité dans un milieu incertain). Yanis affronte un défenseur : **champ 4**. Maëlle présente un enchaînement : **champ 3**. Tom est chronométré : **champ 1**."},{"cle":{"type":"zone","ids":["m34"]},"explication":"« J’avais une **seconde** pour choisir » : dans un affrontement, l’adversaire ne laisse pas le temps de réfléchir longtemps. Il faut décider vite."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 s","explication":"6 min 10 s = 370 s et 5 min 50 s = 350 s. 370 − 350 = **20 secondes** gagnées en un trimestre."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est la **progression** : l’écart avec le point de départ. La performance, elle, serait son temps de décembre (5 min 50 s)."}]$ex$::jsonb),
